('agent-robotics-engineer','Robotics Engineer','Robotics Engineer / Automation / Control Systems','Works on robotic systems, sensors, control loops, simulation, perception, autonomy, and deployment constraints.','Reason about robotics systems with sensors, actuators, control loops, perception, planning, simulation, safety constraints, calibration, and field validation.'),
('agent-ar-vr-designer','AR VR Experience Designer','AR VR Designer / Spatial UX / Immersive Interaction','Designs spatial interfaces, immersive flows, interaction models, comfort, accessibility, and 3D user experience.','Design spatial experiences with interaction models, user comfort, accessibility, scene hierarchy, onboarding, motion constraints, and prototype validation.')
)
INSERT INTO agents (id, name, provider, system_prompt, config, status, created_at, updated_at)
SELECT
    seed.id,
    seed.name,
    provider_choice.provider,
    base_prompt.prompt
        || char(10) || '- Agent name: ' || seed.name
        || char(10) || '- Routing role: ' || seed.name
        || char(10) || '- Professional position: ' || seed.position
        || char(10) || '- Domain details: ' || seed.details
        || char(10) || char(10) || 'Role-specific mission: ' || seed.charter,
    json_object(
        'role', seed.name,
        'position', seed.position,
        'details', seed.details
    ),
    'online',
    ts.now_value,
    ts.now_value
FROM seed
CROSS JOIN provider_choice
CROSS JOIN ts
CROSS JOIN base_prompt
WHERE 1
ON CONFLICT(id) DO UPDATE SET
    name = excluded.name,
    provider = excluded.provider,
    system_prompt = excluded.system_prompt,
    config = excluded.config,
    status = excluded.status,
    updated_at = excluded.updated_at;

COMMIT;
